import sqlite3

def connect(path):
    con = sqlite3.connect(path)
    con.execute("PRAGMA foreign_keys = ON")
    con.execute("PRAGMA busy_timeout = 5000")
    return con

con = connect(":memory:")
con.executescript('''
    CREATE TABLE author (id INTEGER PRIMARY KEY, name TEXT);
    CREATE TABLE book (id INTEGER PRIMARY KEY,
                       author_id INTEGER NOT NULL REFERENCES author(id) ON DELETE CASCADE);
    INSERT INTO author VALUES (1, 'Toumanian');
    INSERT INTO book VALUES (10, 1);
''')
try:
    con.execute("INSERT INTO book VALUES (11, 99)")
except sqlite3.IntegrityError as e:
    print(e)                                              # FOREIGN KEY constraint failed
con.execute("DELETE FROM author WHERE id = 1")
print(con.execute("SELECT count(*) FROM book").fetchone())   # (0,) cascaded
print(con.execute("SELECT name, type FROM pragma_table_info('book')").fetchall())
# [('id', 'INTEGER'), ('author_id', 'INTEGER')]

import sqlite3

MIGRATIONS = [
    "CREATE TABLE user (id INTEGER PRIMARY KEY, name TEXT)",
    "ALTER TABLE user ADD COLUMN email TEXT",
    # v3: make email NOT NULL + UNIQUE -> needs a rebuild
    '''CREATE TABLE user_new (id INTEGER PRIMARY KEY, name TEXT,
                              email TEXT NOT NULL UNIQUE);
       INSERT INTO user_new SELECT id, name, coalesce(email, 'unknown' || id) FROM user;
       DROP TABLE user;
       ALTER TABLE user_new RENAME TO user;''',
]

def migrate(con):
    version = con.execute("PRAGMA user_version").fetchone()[0]
    for number, sql in enumerate(MIGRATIONS[version:], start=version + 1):
        con.executescript(f"BEGIN; {sql}; PRAGMA user_version = {number}; COMMIT;")
    return con.execute("PRAGMA user_version").fetchone()[0]

con = sqlite3.connect(":memory:")
print(migrate(con))                                                   # 3
print(con.execute("SELECT sql FROM sqlite_schema WHERE name = 'user'").fetchone()[0])
